import{z as E,x as S,o as t,c as d,q as r,j as s,D as e,d as i,s as l,S as n}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"三层堆叠 SOC / SOG","description":"","frontmatter":{"title":"三层堆叠 SOC / SOG","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/trilayer-soc-sog.md","filePath":"litho/trilayer-soc-sog.md","lastUpdated":1791063341000}'),A={name:"litho/trilayer-soc-sog.md"};function p(B,a,h,O,C,_){const o=S("Mermaid");return t(),d("div",null,[a[2]||(a[2]=r('<h1 id="三层堆叠-soc-sog" tabindex="-1">三层堆叠 SOC / SOG <a class="header-anchor" href="#三层堆叠-soc-sog" aria-label="Permalink to &quot;三层堆叠 SOC / SOG&quot;">​</a></h1><div class="epigraph"><p>薄成像胶要分辨率与随机性；厚底层要抗刻蚀。SOC / SOG 把两件事拆开，转印多一次开口。</p><footer>—— 对照先进节点 trilayer 公开流程：成像层 / SOG / SOC</footer></div><p><a href="/litho/ebr-edge-bead">上一课</a>切完珠。中心场若只涂一层厚 CAR，<a href="/litho/high-na-resist-budget">高 NA 薄胶</a> 与深宽比会打架。缺口是三层：薄光刻胶成像，SOG（spin-on glass）当硬掩模，SOC（spin-on carbon）当厚有机底层。后课软烤对每一层都做，本课只钉堆叠角色。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单层厚胶：吸收、随机性、倒塌一起坏。单层薄胶：刻蚀预算不够。三层把「谁看见光子」和「谁扛等离子体」分开。缺口不是再写 <a href="/litho/standing-wave-barc">BARC</a> 的反射公式，而是谁开口、谁停。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>自下而上：SOC 填形貌、给碳硬掩模厚度；SOG 给含硅层，对碳有选择比；成像胶薄，只把图形落到 SOG。显影后先开口 SOG，再开口 SOC，再进衬底。每一层旋涂+烘烤，均匀性误差会叠——旋涂课的 \\(d(r)\\) 现在有三张。</p>',7)),(t(),s(n,null,{default:e(()=>[l(o,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20PR%5B%22%E8%96%84%E6%88%90%E5%83%8F%E8%83%B6%22%5D%20--%3E%20SOG%5B%22SOG%22%5D%0A%20%20SOG%20--%3E%20SOC%5B%22SOC%22%5D%0A%20%20SOC%20--%3E%20SUB%5B%22%E8%A1%AC%E5%BA%95%22%5D%0A%20%20PR%20--%3E%20ETCH%5B%22%E5%BC%80%E5%8F%A3%E9%93%BE%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p><span class="marginnote">有的流程用 CVD 硬掩模替换 SOG。名字变了，分工不变：成像层薄、转印层抗刻蚀。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p><span class="marginnote">SOC 与 SOG 翻译开：SOC 是「旋涂碳」，一大桶含碳有机物旋上去、烘成厚实的抗刻蚀垫；SOG 是「旋涂玻璃」，含硅，在氧化性等离子体里比碳耐烧。一软一硬，各扛一段。</span></p><p>含硅层在氧化性等离子体里相对碳更耐或相反，取决于气体——选择比是刻蚀课，本课只要求存在一层「停得住」的中间膜。SOC 的填孔能力决定下层金属沟槽上还要不要再平坦化。</p><p><span class="marginnote">为什么每一步都要「停得住」：刻 SOG 时若把下面的 SOC 也咬掉一点，失真会沿着开口链一路放大到衬底。选择比说的就是「该开的层快走、该停的层纹丝不动」——一处失守，整条链作废。</span></p>',5)),(t(),s(n,null,{default:e(()=>[l(o,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20LR%0A%20%20DEV%5B%22%E6%98%BE%E5%BD%B1%3A%20%E8%83%B6%E4%B8%AD%E5%9B%BE%E5%BD%A2%22%5D%20--%3E%20E1%5B%22%E5%88%BB%201%3A%20%E8%83%B6%E5%BC%80%E5%8F%A3%20SOG%22%5D%0A%20%20E1%20--%3E%20ST1%5B%22%E5%81%9C%3A%20SOG%20%E5%AF%B9%E8%83%B6%E7%9A%84%E9%80%89%E6%8B%A9%E6%AF%94%22%5D%0A%20%20ST1%20--%3E%20E2%5B%22%E5%88%BB%202%3A%20SOG%20%E5%BC%80%E5%8F%A3%20SOC%22%5D%0A%20%20E2%20--%3E%20ST2%5B%22%E5%81%9C%3A%20SOC%20%E5%8E%9A%E7%A2%B3%E6%8E%A9%E6%A8%A1%22%5D%0A%20%20ST2%20--%3E%20E3%5B%22%E5%88%BB%203%3A%20SOC%20%E5%BC%80%E5%8F%A3%E8%BF%9B%E8%A1%AC%E5%BA%95%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 DSA 或金属氧化物胶替代三层。下一课软烤：溶剂走了，堆叠才变成可曝光固体。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三层拆开成像厚度与刻蚀厚度。</li><li>误差按层叠加；开口链是后课 BARC/硬掩模刻蚀的前置。</li><li>出处：先进节点 trilayer 公开流程通识。</li></ul><p><span class="marginnote">三层堆叠可以类比盖章：薄胶是最上面那张描图纸，清晰但不禁磨；SOG 是复写纸；SOC 是垫板——字迹经描图纸落下来，真正吃刻蚀大力气的是垫板。三层各有厚度预算，均匀性误差也就有三份。</span></p>',5))])}const T=E(A,[["render",p]]);export{m as __pageData,T as default};
